mapper.select:
SELECT FROM t_organization_unit WHERE placeholder=0 AND id IN
#{organizationUnitId}
ORDER BY CASE WHEN parent_id IS NULL THEN 0 ELSE 1 END, parent_id, order_no, id

mapper.update:
UPDATE t_organization_unit
SET leader_employee_id=#{leaderEmployeeId},version=version+1,
    edit_by=#{operatorId},edit_time=#{editTime}
WHERE id=#{organizationUnitId} AND version=#{expectedVersion}
  AND type='COMPANY' AND parent_id IS NULL
  AND leader_employee_id IS NULL AND placeholder=0 AND enabled=1
